def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    units = max(1, int(supply // WATER_REQ))
    scarcity = len(alive) + 1 - units

    opp_scores = []
    prev_bids = []
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid', 0) or 0
        prev_bids.append(prev_bid)

        need = 0.0
        if opp.get('no_water_days', 0) >= 1:
            need += 18.0
        if opp.get('hp', 10) <= 4:
            need += 16.0
        elif opp.get('hp', 10) <= 7:
            need += 8.0
        if opp.get('budget', 0) > 200:
            need += 6.0
        if prev.get('status') == 'won':
            need += 4.0
        if prev_bid >= 100:
            need += 8.0
        elif prev_bid >= 70:
            need += 4.0

        score_bid = prev_bid + need
        opp_scores.append(score_bid)

    highest_prev = max(prev_bids) if prev_bids else 0
    pressure_bid = max(opp_scores) if opp_scores else 0

    desperate = hp <= 3 or no_water_days >= 1
    very_safe = hp >= 8 and no_water_days == 0

    if desperate:
        if scarcity >= 3:
            bid = max(pressure_bid + 10.0, DAILY_SALARY * 1.45)
        elif scarcity >= 2:
            bid = max(pressure_bid + 7.0, DAILY_SALARY * 1.15)
        else:
            bid = max(pressure_bid + 4.0, DAILY_SALARY * 0.95)
    else:
        if scarcity >= 3:
            bid = max(pressure_bid + 5.0, DAILY_SALARY * 0.95)
        elif scarcity >= 2:
            bid = max(pressure_bid + 2.5, DAILY_SALARY * 0.72)
        elif scarcity >= 1:
            if very_safe and highest_prev >= 110:
                bid = DAILY_SALARY * 0.34
            else:
                bid = max(DAILY_SALARY * 0.52, pressure_bid * 0.78)
        else:
            if very_safe:
                bid = DAILY_SALARY * 0.28
            else:
                bid = DAILY_SALARY * 0.4

    if day >= 8 and hp >= 6 and no_water_days == 0 and scarcity <= 1:
        bid = min(bid, DAILY_SALARY * 0.45)

    reserve_floor = 0.0
    if hp >= 5:
        reserve_floor = 40.0
    if budget <= reserve_floor:
        bid = min(bid, max(0.0, budget * 0.6))

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how tight the market is: fewer units when supply is lower
    # (We don't know exact allocation mechanics, so we bias toward mid bids.)
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base willingness: mid-level to beat overbidders without burning budget.
    # If supply is low, raise slightly.
    base = DAILY_SALARY * (0.48 + 0.12 * (1.0 - supply_ratio))

    # If yesterday's max bid was very high, pressure is high; respond.
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        if hp <= 2.5 or no_water_days >= 1:
            bid = DAILY_SALARY * 0.92
        else:
            bid = DAILY_SALARY * 0.62
    elif highest_prev_bid >= DAILY_SALARY * 1.2:
        if hp <= 2.5:
            bid = DAILY_SALARY * 0.80
        else:
            bid = DAILY_SALARY * 0.55
    else:
        # If opponents didn't overbid yesterday, try to secure with a modest edge.
        bid = base

    # Keep bids within budget and avoid extreme overspending.
    # Also, if budget is very low, bid as much as possible without going negative.
    bid = float(min(budget, bid))

    # If critically low HP, spend more aggressively.
    if hp <= 1.5:
        bid = float(min(budget, max(bid, DAILY_SALARY * 0.98)))

    # If we have already gone without water, increase odds.
    if no_water_days >= 2:
        bid = float(min(budget, max(bid, DAILY_SALARY * 0.75)))

    # Final clamp to non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    supply = day_context['supply']
    num_alive_agents = len(alive_opponents) + 1 

    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.95)
    if my_hp <= 5:
        return min(my_budget, DAILY_SALARY * 0.85)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = DAILY_SALARY * 0.6 

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_hp > 7 and current_day < EPISODE_DAYS - 2:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    if supply < num_alive_agents * WATER_REQ * 0.6:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)
    elif supply < num_alive_agents * WATER_REQ * 0.4:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    days_left = EPISODE_DAYS - current_day + 1
    if days_left <= 3:
        if my_hp <= 7:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_budget, base_bid)

    final_bid = max(final_bid, DAILY_SALARY * 0.05) 

    return final_bid
